mapper.select:
SELECT DISTINCT p.id, p.kakao_id, p.place_name, p.address_name, p.road_address_name, p.latitude, p.longitude, p.phone, p.save_count, p.category_id, c.name AS category_name FROM places p JOIN my_places mp ON mp.place_id = p.id JOIN members m ON m.id = mp.member_id JOIN members_characters mc ON mc.member_id = m.id LEFT JOIN places_categories c ON c.id = p.category_id WHERE mc.character_id IN
#{characterId}
AND m.id != #{excludeMemberId} ORDER BY p.save_count DESC LIMIT #{limit}
